local PidPacketSender = T(Global, "PidPacketSender")

function PidPacketSender:sendShopTip(userId, str)
    local player = PlayerManager:getPlayerByUserId(userId)
    if not player then
        return
    end
    player:sendPacket({
        pid = "showTip",
        str = str
    })
end

return PidPacketSender